        if upstream.returncode == 0 and upstream.stdout.strip():
            ahead = git(["rev-list", "--count", f"{upstream.stdout.strip()}..{branch}"], project)
            if ahead.returncode == 0 and ahead.stdout.strip() not in ("", "0"):
